data class Money(val minor: Long, val currency: Currency) {
    init { require(minor >= 0) { "amount" } }

    operator fun plus(other: Money): Money {
        require(currency == other.currency) { "currency mismatch" }
        return Money(minor + other.minor, currency)
    }
    operator fun times(factor: Int): Money = Money(minor * factor, currency)

    companion object { fun zero(currency: Currency) = Money(0, currency) }
}
